SELECT DISTINCT Client.numcli,Site.mntredev,Site.surven,Client.nomcli,Site.nomsit,Site.typsit,Site.adrsit,Site.codpossit,Site.vilsit,Site.numsit,Site.nbrentsit FROM [ZoneGeographique],[Intervenant],[Client],[Site],[Intervention],[Parametre] WHERE (((Client.numcli)=[Parametre].[numcli]) AND ((Site.numcli)=[Client].[numcli]) AND ((Intervention.cptsit)=[Site].[cptsit]) AND ((Intervention.typint)<>'6') AND ((Intervenant.numzonint)=[ZoneGeographique].[numzon])) 
